function rampartSimulate(createStrategy, seed, maxTicks, rec) {
  'use strict';
  // ---------------------------------------------------------------- tables
  var TYPE_NAMES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
  var TDEF = {
    bolt:   { cost: 50,  dmg: 26,  per: 8,  range: 300, splash: 0,  slow: 0,  pierce: 0, ground: 1, air: 1 },
    cannon: { cost: 90,  dmg: 60,  per: 24, range: 260, splash: 90, slow: 0,  pierce: 0, ground: 1, air: 0 },
    frost:  { cost: 70,  dmg: 10,  per: 12, range: 240, splash: 0,  slow: 30, pierce: 0, ground: 1, air: 1 },
    lance:  { cost: 120, dmg: 180, per: 36, range: 360, splash: 0,  slow: 0,  pierce: 1, ground: 1, air: 0 },
    flak:   { cost: 80,  dmg: 40,  per: 10, range: 320, splash: 70, slow: 0,  pierce: 0, ground: 0, air: 1 }
  };
  var ENEMY_NAMES = ['grunt', 'runner', 'wisp', 'brute', 'splitter', 'mender', 'splitling'];
  //                  hp  speed bounty leak air first weight
  var EDEF = [
    { hp: 60,  speed: 10, bounty: 4, leak: 1, air: 0, first: 1, weight: 10 },
    { hp: 40,  speed: 20, bounty: 4, leak: 1, air: 0, first: 2, weight: 4 },
    { hp: 50,  speed: 12, bounty: 6, leak: 2, air: 1, first: 3, weight: 3 },
    { hp: 150, speed: 6,  bounty: 9, leak: 3, air: 0, first: 4, weight: 3 },
    { hp: 90,  speed: 8,  bounty: 6, leak: 2, air: 0, first: 6, weight: 2 },
    { hp: 70,  speed: 8,  bounty: 7, leak: 2, air: 0, first: 8, weight: 1 },
    { hp: 0,   speed: 12, bounty: 1, leak: 1, air: 0, first: 99, weight: 0 }
  ];
  var SPLITLING = 6;
  var SLOTS = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8],
               [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  var ROUTE_PTS = [
    [[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]],
    [[0, 6], [21, 6], [21, 11], [23, 11]]
  ];
  var BASE_START_HP = 10, GOLD_START = 250;

  // route lookup: position at every integer progress
  var ROUTE_X = [], ROUTE_Y = [], ROUTE_LEN = [];
  (function () {
    for (var r = 0; r < 2; r++) {
      var pts = ROUTE_PTS[r], xs = [], ys = [];
      var px = pts[0][0] * 100 + 50, py = pts[0][1] * 100 + 50;
      xs.push(px); ys.push(py);
      for (var i = 1; i < pts.length; i++) {
        var tx = pts[i][0] * 100 + 50, ty = pts[i][1] * 100 + 50;
        var dx = tx > px ? 1 : tx < px ? -1 : 0, dy = ty > py ? 1 : ty < py ? -1 : 0;
        while (px !== tx || py !== ty) { px += dx; py += dy; xs.push(px); ys.push(py); }
      }
      ROUTE_X.push(xs); ROUTE_Y.push(ys); ROUTE_LEN.push(xs.length - 1);
    }
  })();

  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }

  var mTable = [0, 1000];
  function mult(w) {
    while (mTable.length <= w) mTable.push(Math.floor(mTable[mTable.length - 1] * 108 / 100));
    return mTable[w];
  }
  function armorOf(t, w) {
    if (t === 0) return Math.floor(w / 4);
    if (t === 3) return 6 + w;
    return 0;
  }

  // ---------------------------------------------------------------- state
  var rng = mulberry32(seed);
  var waves = [null];                    // waves[w] = array of type indices
  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), avail = [], total = 0, i;
    for (i = 0; i < 6; i++) if (EDEF[i].first <= w) { avail.push(i); total += EDEF[i].weight; }
    var list = [];
    for (i = 0; i < n; i++) {
      var r = rng() % total, k = 0;
      while (r >= EDEF[avail[k]].weight) { r -= EDEF[avail[k]].weight; k++; }
      list.push(avail[k]);
    }
    waves[w] = list;
  }
  genWave(1);

  var gold = GOLD_START, baseHp = BASE_START_HP;
  var turrets = [];                      // by slot: null | turret
  for (var si = 0; si < 16; si++) turrets.push(null);
  var enemies = [];                      // ascending id
  var queue = [];                        // spawn queue {tick, wave, idx, t}
  var nextId = 1, log = [], wave = 0, fallTick = -1, endTick = maxTicks;
  var strategy = createStrategy();
  var ev = rec ? [] : null;              // per-tick visual events (recorder only)

  function view(e) {
    return { id: e.id, type: ENEMY_NAMES[e.t], hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y,
             air: e.air, armor: e.armor, speed: EDEF[e.t].speed, slowed: e.slow > 0 ? 1 : 0,
             remaining: ROUTE_LEN[e.air] - e.progress };
  }
  function makeEnemy(t, w, maxHp, progress) {
    var air = EDEF[t].air;
    var e = { id: nextId++, t: t, wave: w, maxHp: maxHp, hp: maxHp, progress: progress, air: air,
              armor: armorOf(t, w), slow: 0, age: 0, x: ROUTE_X[air][progress], y: ROUTE_Y[air][progress] };
    return e;
  }
  function pushLog(tick, code, a, b) { log.push([tick, code, a, b]); }

  function applyActions(tick, actions) {
    if (!actions || typeof actions.length !== 'number') return;
    var n = Math.min(actions.length, 32);
    for (var i = 0; i < n; i++) {
      var a = actions[i];
      if (!a || typeof a !== 'object') continue;
      var slot = a.slot;
      if (typeof slot !== 'number' || slot !== Math.floor(slot) || slot < 0 || slot > 15) continue;
      var tu = turrets[slot];
      if (a.op === 'build') {
        var def = TDEF[a.type];
        if (!def || !Object.prototype.hasOwnProperty.call(TDEF, a.type)) continue;
        if (tu || gold < def.cost) continue;
        gold -= def.cost;
        turrets[slot] = { type: a.type, ti: TYPE_NAMES.indexOf(a.type), tier: 1, spent: def.cost, cd: 0,
                          dmg: def.dmg, range: def.range };
        pushLog(tick, 'B', slot, turrets[slot].ti);
        if (ev) ev.push(['B', slot, turrets[slot].ti, 1]);
      } else if (a.op === 'upgrade') {
        if (!tu || tu.tier >= 3) continue;
        var d2 = TDEF[tu.type], cost = d2.cost * tu.tier;
        if (gold < cost) continue;
        gold -= cost; tu.spent += cost; tu.tier++;
        tu.dmg = Math.floor(tu.dmg * 16 / 10); tu.range += 30;
        pushLog(tick, 'U', slot, tu.tier);
        if (ev) ev.push(['U', slot, tu.ti, tu.tier]);
      } else if (a.op === 'sell') {
        if (!tu) continue;
        gold += Math.floor(tu.spent * 70 / 100);
        turrets[slot] = null;
        pushLog(tick, 'S', slot, 0);
        if (ev) ev.push(['S', slot, tu.ti, tu.tier]);
      }
    }
  }

  function removeDead(tick, slot) {
    // remove every enemy with hp <= 0 in ascending id order, pay bounty, spawn splitlings
    var kept = null, i, e;
    for (i = 0; i < enemies.length; i++) {
      e = enemies[i];
      if (e.hp <= 0) { kept = true; break; }
    }
    if (!kept) return;
    var out = [], born = [];
    for (i = 0; i < enemies.length; i++) {
      e = enemies[i];
      if (e.hp > 0) { out.push(e); continue; }
      gold += EDEF[e.t].bounty;
      pushLog(tick, 'K', e.id, slot);
      if (ev) ev.push(['K', e.id, e.t, e.x, e.y, slot, e.wave, e.air]);
      if (e.t === 4) {
        var hp = Math.max(1, Math.floor(e.maxHp / 4));
        var ids = [];
        for (var c = 0; c < 3; c++) { var s = makeEnemy(SPLITLING, e.wave, hp, e.progress); born.push(s); ids.push(s.id); }
        if (ev) ev.push(['P', e.id, e.x, e.y, ids[0], ids[1], ids[2]]);
      }
    }
    for (i = 0; i < born.length; i++) out.push(born[i]);   // new ids are the largest: order stays ascending
    enemies = out;
  }

  // ------------------------------------------------------------------ loop
  for (var tick = 0; tick < maxTicks; tick++) {
    if (ev) ev.length = 0;
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      var w = (tick - 20) / 40 + 1;
      wave = w;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * w;
      genWave(w + 1);
      var slotsView = [];
      for (var s = 0; s < 16; s++) {
        var tt = turrets[s];
        slotsView.push({ slot: s, x: SLOTS[s][0], y: SLOTS[s][1],
                         turret: tt ? { type: tt.type, tier: tt.tier, spent: tt.spent } : null });
      }
      var evs = [];
      for (var q = 0; q < enemies.length; q++) evs.push(view(enemies[q]));
      var nextNames = [];
      for (var nq = 0; nq < waves[w + 1].length; nq++) nextNames.push(ENEMY_NAMES[waves[w + 1][nq]]);
      var st = { tick: tick, wave: w, gold: gold, baseHp: baseHp, slots: slotsView, enemies: evs, nextWave: nextNames };
      if (rec && rec.beforePlan) rec.beforePlan(tick, w, waves[w + 1]);
      applyActions(tick, strategy.plan(st));
      var wl = waves[w];
      for (var wi = 0; wi < wl.length; wi++) queue.push({ tick: tick + 4 * wi, wave: w, idx: wi, t: wl[wi] });
      // queue is generated in (wave, idx) order and waves start in increasing ticks; keep it sorted
      // by tick, then wave, then index (a stable insertion sort of the tail suffices)
      for (var a1 = 1; a1 < queue.length; a1++) {
        var cur = queue[a1], b1 = a1 - 1;
        while (b1 >= 0 && (queue[b1].tick > cur.tick || (queue[b1].tick === cur.tick && (queue[b1].wave > cur.wave ||
               (queue[b1].wave === cur.wave && queue[b1].idx > cur.idx))))) { queue[b1 + 1] = queue[b1]; b1--; }
        queue[b1 + 1] = cur;
      }
    }
    // 2. spawn
    var qn = 0;
    while (qn < queue.length && queue[qn].tick <= tick) {
      var qe = queue[qn++];
      var mhp = Math.floor(EDEF[qe.t].hp * mult(qe.wave) / 1000);
      var ne = makeEnemy(qe.t, qe.wave, mhp, 0);
      enemies.push(ne);
      if (ev) ev.push(['N', ne.id, ne.t, qe.wave]);
    }
    if (qn) queue.splice(0, qn);
    // 3. move
    var fell = false;
    for (var mi = 0; mi < enemies.length; mi++) {
      var me = enemies[mi];
      var spd = EDEF[me.t].speed;
      if (me.slow > 0) spd = Math.floor(spd * 60 / 100);
      me.progress += spd;
      if (me.progress >= ROUTE_LEN[me.air]) {
        baseHp -= EDEF[me.t].leak;
        pushLog(tick, 'L', me.id, baseHp);
        me.dead = 1;
        if (ev) ev.push(['L', me.id, me.t, ROUTE_X[me.air][ROUTE_LEN[me.air]], ROUTE_Y[me.air][ROUTE_LEN[me.air]], me.air, baseHp]);
        enemies.splice(mi, 1); mi--;
        if (baseHp <= 0) { fell = true; break; }
      } else {
        me.x = ROUTE_X[me.air][me.progress]; me.y = ROUTE_Y[me.air][me.progress];
      }
    }
    if (fell) {
      fallTick = tick; endTick = tick;
      pushLog(tick, 'F', wave, 0);
      if (ev) ev.push(['F', wave]);
      if (rec && rec.tick) rec.tick(tick, enemies, turrets, baseHp, gold, wave, ev, true);
      break;
    }
    // 4. age & heal
    for (var ai = 0; ai < enemies.length; ai++) {
      var ae = enemies[ai];
      ae.age++;
      if (ae.t === 5 && ae.age % 20 === 0) {
        for (var hi = 0; hi < enemies.length; hi++) {
          var he = enemies[hi], hx = he.x - ae.x, hy = he.y - ae.y;
          if (hx * hx + hy * hy <= 150 * 150) {
            he.hp = Math.min(he.maxHp, he.hp + Math.floor(he.maxHp * 8 / 100));
          }
        }
        if (ev) ev.push(['H', ae.id, ae.x, ae.y]);
      }
    }
    // 5. turrets fire
    for (var ti = 0; ti < 16; ti++) {
      var tu = turrets[ti];
      if (!tu) continue;
      if (tu.cd > 0) tu.cd--;
      if (tu.cd > 0) continue;
      var def = TDEF[tu.type];
      var tx = SLOTS[ti][0] * 100 + 50, ty = SLOTS[ti][1] * 100 + 50, r2 = tu.range * tu.range;
      var cands = [], best = null;
      for (var ci = 0; ci < enemies.length; ci++) {
        var ce = enemies[ci];
        if (ce.air ? !def.air : !def.ground) continue;
        var dx = ce.x - tx, dy = ce.y - ty;
        if (dx * dx + dy * dy > r2) continue;
        cands.push(ce);
        if (best === null || (ROUTE_LEN[ce.air] - ce.progress) < (ROUTE_LEN[best.air] - best.progress)) best = ce;
      }
      if (!cands.length) continue;
      var target = best;
      if (typeof strategy.target === 'function') {
        var cv = [];
        for (var cvi = 0; cvi < cands.length; cvi++) cv.push(view(cands[cvi]));
        var pick = strategy.target({ slot: ti, type: tu.type, tier: tu.tier, x: tx, y: ty, range: tu.range }, cv);
        for (var pi = 0; pi < cands.length; pi++) if (cands[pi].id === pick) { target = cands[pi]; break; }
      }
      // deal damage
      var hits = [];
      if (def.splash > 0) {
        var sr2 = def.splash * def.splash;
        for (var si2 = 0; si2 < enemies.length; si2++) {
          var se = enemies[si2];
          if (se.air ? !def.air : !def.ground) continue;
          var sx = se.x - target.x, sy = se.y - target.y;
          if (sx * sx + sy * sy <= sr2) hits.push(se);
        }
      } else hits.push(target);
      for (var hh = 0; hh < hits.length; hh++) {
        var h = hits[hh];
        var dmg = def.pierce ? tu.dmg : Math.max(1, tu.dmg - h.armor);
        h.hp -= dmg;
        if (def.slow > 0) h.slow = def.slow;
      }
      tu.cd = def.per;
      if (ev) ev.push(['T', ti, tu.ti, tu.tier, target.id, target.x, target.y, target.air, hits.length]);
      removeDead(tick, ti);
    }
    // 6. slow timers
    for (var zi = 0; zi < enemies.length; zi++) if (enemies[zi].slow > 0) enemies[zi].slow--;
    if (rec && rec.tick) rec.tick(tick, enemies, turrets, baseHp, gold, wave, ev, false);
  }

  // ------------------------------------------------------------------ result
  var h32 = 0x811c9dc5, js = JSON.stringify(log);
  for (var hc = 0; hc < js.length; hc++) { h32 ^= js.charCodeAt(hc); h32 = Math.imul(h32, 0x01000193); }
  var hex = (h32 >>> 0).toString(16);
  while (hex.length < 8) hex = '0' + hex;
  var score = Math.round(((endTick - 20) / 40) * 100) / 100;
  return { score: score, fallTick: fallTick, log: log, hash: hex };
}

