        me.x = ROUTE_X[me.air][me.progress]; me.y = ROUTE_Y[me.air][me.progress];
      }
    }
    if (fell) {
      fallTick = tick; endTick = tick;
      pushLog(tick, 'F', wave, 0);
      if (ev) ev.push(['F', wave]);
      if (rec && rec.tick) rec.tick(tick, enemies, turrets, baseHp, gold, wave, ev, true);
      break;
    }
    // 4. age & heal
    for (var ai = 0; ai < enemies.length; ai++) {
      var ae = enemies[ai];
      ae.age++;
      if (ae.t === 5 && ae.age % 20 === 0) {
        for (var hi = 0; hi < enemies.length; hi++) {
          var he = enemies[hi], hx = he.x - ae.x, hy = he.y - ae.y;
          if (hx * hx + hy * hy <= 150 * 150) {
            he.hp = Math.min(he.maxHp, he.hp + Math.floor(he.maxHp * 8 / 100));
          }
        }
        if (ev) ev.push(['H', ae.id, ae.x, ae.y]);
      }
    }
    // 5. turrets fire
    for (var ti = 0; ti < 16; ti++) {
      var tu = turrets[ti];
      if (!tu) continue;
      if (tu.cd > 0) tu.cd--;
      if (tu.cd > 0) continue;
      var def = TDEF[tu.type];
      var tx = SLOTS[ti][0] * 100 + 50, ty = SLOTS[ti][1] * 100 + 50, r2 = tu.range * tu.range;
      var cands = [], best = null;
      for (var ci = 0; ci < enemies.length; ci++) {
        var ce = enemies[ci];
        if (ce.air ? !def.air : !def.ground) continue;
        var dx = ce.x - tx, dy = ce.y - ty;
        if (dx * dx + dy * dy > r2) continue;
        cands.push(ce);
        if (best === null || (ROUTE_LEN[ce.air] - ce.progress) < (ROUTE_LEN[best.air] - best.progress)) best = ce;
      }
      if (!cands.length) continue;
      var target = best;
      if (typeof strategy.target === 'function') {
        var cv = [];
        for (var cvi = 0; cvi < cands.length; cvi++) cv.push(view(cands[cvi]));
        var pick = strategy.target({ slot: ti, type: tu.type, tier: tu.tier, x: tx, y: ty, range: tu.range }, cv);
        for (var pi = 0; pi < cands.length; pi++) if (cands[pi].id === pick) { target = cands[pi]; break; }
      }
      // deal damage
      var hits = [];
      if (def.splash > 0) {
        var sr2 = def.splash * def.splash;
        for (var si2 = 0; si2 < enemies.length; si2++) {
          var se = enemies[si2];
          if (se.air ? !def.air : !def.ground) continue;
          var sx = se.x - target.x, sy = se.y - target.y;
          if (sx * sx + sy * sy <= sr2) hits.push(se);
        }
      } else hits.push(target);
      for (var hh = 0; hh < hits.length; hh++) {
        var h = hits[hh];
        var dmg = def.pierce ? tu.dmg : Math.max(1, tu.dmg - h.armor);
        h.hp -= dmg;
        if (def.slow > 0) h.slow = def.slow;
      }
      tu.cd = def.per;
      if (ev) ev.push(['T', ti, tu.ti, tu.tier, target.id, target.x, target.y, target.air, hits.length]);
      removeDead(tick, ti);
    }
    // 6. slow timers
    for (var zi = 0; zi < enemies.length; zi++) if (enemies[zi].slow > 0) enemies[zi].slow--;
    if (rec && rec.tick) rec.tick(tick, enemies, turrets, baseHp, gold, wave, ev, false);
  }

  // ------------------------------------------------------------------ result
  var h32 = 0x811c9dc5, js = JSON.stringify(log);
  for (var hc = 0; hc < js.length; hc++) { h32 ^= js.charCodeAt(hc); h32 = Math.imul(h32, 0x01000193); }
  var hex = (h32 >>> 0).toString(16);
  while (hex.length < 8) hex = '0' + hex;
  var score = Math.round(((endTick - 20) / 40) * 100) / 100;
  return { score: score, fallTick: fallTick, log: log, hash: hex };
}

