// Genome-driven strategy + evolutionary search harness (jsc).
load('sim.js');

var TN = ['bolt', 'cannon', 'frost', 'lance', 'flak'];

// strategy factory from genome: {ops:[[0,slot,type],[1,slot],[2,slot]...], tm:[...5], pm:[...5]}
function makeFactory(G) {
  return function createStrategy() {
    var COST = [50, 90, 70, 120, 80];
    var BASE = [26, 60, 10, 180, 40], RNG = [300, 260, 240, 360, 320], SPL = [0, 90, 0, 0, 70];
    var PIERCE = [0, 0, 0, 1, 0];
    var ops = G.ops, idx = 0, tm = G.tm, pm = G.pm;
    var TIDX = { bolt: 0, cannon: 1, frost: 2, lance: 3, flak: 4 };
    var dmgTab = [];
    for (var ty = 0; ty < 5; ty++) { var d = BASE[ty], row = [d]; d = Math.floor(d * 16 / 10); row.push(d); d = Math.floor(d * 16 / 10); row.push(d); dmgTab.push(row); }
    return {
      plan: function (s) {
        var acts = [], g = s.gold;
        var cur = [];
        for (var i = 0; i < 16; i++) { var t = s.slots[i].turret; cur.push(t ? { ty: TIDX[t.type], tier: t.tier, spent: t.spent } : null); }
        while (idx < ops.length) {
          var o = ops[idx];
          var sl = o[1], c = cur[sl];
          if (o[0] === 0) {
            if (c) { idx++; continue; }
            var cost = COST[o[2]];
            if (g < cost) break;
            g -= cost; cur[sl] = { ty: o[2], tier: 1, spent: cost };
            acts.push({ op: 'build', slot: sl, type: TN[o[2]] });
          } else if (o[0] === 1) {
            if (!c || c.tier >= 3) { idx++; continue; }
            var uc = COST[c.ty] * c.tier;
            if (g < uc) break;
            g -= uc; c.spent += uc; c.tier++;
            acts.push({ op: 'upgrade', slot: sl });
          } else {
            if (!c) { idx++; continue; }
            g += Math.floor(c.spent * 70 / 100); cur[sl] = null;
            acts.push({ op: 'sell', slot: sl });
          }
          idx++;
        }
        return acts;
      },
      target: function (t, cs) {
        var ty = TIDX[t.type], mode = tm[ty], pri = pm[ty];
        if (mode === 0 && !pri) return -1;
        var best = -1, bs = -1e18, i, c, sc;
        var dm = dmgTab[ty][t.tier - 1];
        for (i = 0; i < cs.length; i++) {
          c = cs[i];
          if (mode === 0) sc = -c.remaining;
          else if (mode === 1) sc = c.hp;
          else if (mode === 2) sc = c.armor * 100000 - c.remaining;
          else if (mode === 3) {
            var n = 0; for (var j = 0; j < cs.length; j++) { var dx = cs[j].x - c.x, dy = cs[j].y - c.y; if (dx * dx + dy * dy <= SPL[ty] * SPL[ty]) n++; }
            sc = n * 100000 - c.remaining;
          } else if (mode === 4) sc = (c.slowed ? 0 : 100000) - c.remaining;
          else if (mode === 5) sc = -c.hp * 10000 - c.remaining;
          else { var eff = PIERCE[ty] ? dm : Math.max(1, dm - c.armor); sc = Math.min(c.hp, eff) * 100000 - c.remaining; }
          if (pri && c.type === 'mender') sc += 1e9;
          if (sc > bs) { bs = sc; best = c.id; }
        }
        return best;
      }
    };
  };
}

function evalGenome(G, seeds, detail) {
  var f = makeFactory(G), tot = 0, arr = [];
  for (var i = 0; i < seeds.length; i++) { var r = rampartSimulate(f, seeds[i], 12020); tot += r.score; if (detail) arr.push(r.score); }
  return detail ? { mean: tot / seeds.length, arr: arr } : tot / seeds.length;
}

function seedRange(a, n) { var r = []; for (var i = 0; i < n; i++) r.push(a + i); return r; }

// simple rng for search
function mkrng(a) { return function () { a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }

