          } else if (mode === 4) sc = (c.slowed ? 0 : 100000) - c.remaining;
          else if (mode === 5) sc = -c.hp * 10000 - c.remaining;
          else { var eff = PIERCE[ty] ? dm : Math.max(1, dm - c.armor); sc = Math.min(c.hp, eff) * 100000 - c.remaining; }
          if (pri && c.type === 'mender') sc += 1e9;
          if (sc > bs) { bs = sc; best = c.id; }
        }
        return best;
      }
    };
  };
}

