  var f = makeFactory(G), tot = 0, arr = [];
  for (var i = 0; i < seeds.length; i++) { var r = rampartSimulate(f, seeds[i], 12020); tot += r.score; if (detail) arr.push(r.score); }
  return detail ? { mean: tot / seeds.length, arr: arr } : tot / seeds.length;
}

function seedRange(a, n) { var r = []; for (var i = 0; i < n; i++) r.push(a + i); return r; }

// simple rng for search
function mkrng(a) { return function () { a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }

