load('gen.js');
// usage: jsc search.js -- searchSeed iters trainStart trainN [startFile]
var SS = +arguments[0], ITERS = +arguments[1], TS = +arguments[2], TN_ = +arguments[3], startFile = arguments[4];
var rnd = mkrng(SS * 7919 + 13);
function ri(n) { return Math.floor(rnd() * n); }
var seeds = seedRange(TS, TN_);

function clone(G) { return JSON.parse(JSON.stringify(G)); }
function initGenome() {
  var G = { ops: [], tm: [0, 0, 0, 0, 0], pm: [0, 0, 0, 0, 0] };
  var order = [1, 3, 6, 5, 11, 9, 12, 7, 13, 4, 8, 10, 2, 0, 14, 15];
  for (var i = 0; i < order.length; i++) G.ops.push([0, order[i], 0]);
  for (var r = 0; r < 2; r++) for (i = 0; i < order.length; i++) G.ops.push([1, order[i]]);
  return G;
}
function mutate(G) {
  var H = clone(G), k = 1 + (rnd() < 0.3 ? 1 : 0) + (rnd() < 0.1 ? 1 : 0);
  for (var m = 0; m < k; m++) {
    var r = rnd(), ops = H.ops, n = ops.length, i, j, o;
    if (r < 0.20) { // change build type
      var bs = []; for (i = 0; i < n; i++) if (ops[i][0] === 0) bs.push(i);
      if (bs.length) ops[bs[ri(bs.length)]][2] = ri(5);
    } else if (r < 0.40) { // swap nearby
      i = ri(n); j = Math.max(0, Math.min(n - 1, i + (ri(9) - 4))); o = ops[i]; ops[i] = ops[j]; ops[j] = o;
    } else if (r < 0.55) { // move
      i = ri(n); o = ops.splice(i, 1)[0]; j = Math.max(0, Math.min(ops.length, i + (ri(21) - 10))); ops.splice(j, 0, o);
    } else if (r < 0.68) { // insert
      var kind = rnd(); var s = ri(16);
      o = kind < 0.35 ? [0, s, ri(5)] : kind < 0.85 ? [1, s] : [2, s];
      ops.splice(ri(n + 1), 0, o);
    } else if (r < 0.76) { // delete
      if (n > 10) ops.splice(ri(n), 1);
    } else if (r < 0.86) { // relabel slots a<->b
      var a = ri(16), b = ri(16);
      for (i = 0; i < n; i++) { if (ops[i][1] === a) ops[i][1] = b; else if (ops[i][1] === b) ops[i][1] = a; }
    } else if (r < 0.93) { // type for all builds at a slot
      var sl = ri(16), t = ri(5);
      for (i = 0; i < n; i++) if (ops[i][0] === 0 && ops[i][1] === sl) ops[i][2] = t;
    } else if (r < 0.97) { H.tm[ri(5)] = ri(7); }
    else { var q = ri(5); H.pm[q] = 1 - H.pm[q]; }
  }
  return H;
}

var cur = startFile ? JSON.parse(read(startFile)) : initGenome();
var curS = evalGenome(cur, seeds);
var best = cur, bestS = curS;
print('START', curS.toFixed(3));
for (var it = 0; it < ITERS; it++) {
  var c = mutate(cur);
  var s = evalGenome(c, seeds);
  if (s >= curS) {
    var improved = s > curS + 1e-9;
    cur = c; curS = s;
    if (s > bestS) { best = c; bestS = s; print('IMPROVE it=' + it + ' ' + s.toFixed(3)); }
  }
}
print('FINAL ' + bestS.toFixed(3));
print('GENOME ' + JSON.stringify(best));

