import sys, os
from playwright.sync_api import sync_playwright

dev = os.path.dirname(os.path.abspath(__file__))
three = open(os.path.join(dev, 'three.min.js'), 'rb').read()

html = """<!doctype html><html><body style="margin:0"><canvas id="stage" style="width:100vw;height:100vh"></canvas>
<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
try {
const r = new THREE.WebGLRenderer({canvas: document.getElementById('stage'), antialias:true, alpha:true});
r.setSize(400,300,false);
const gl = r.getContext();
window.__info = [THREE.REVISION, gl.getParameter(gl.VERSION), r.capabilities.isWebGL2];
const s = new THREE.Scene(); const c = new THREE.PerspectiveCamera(50,4/3,0.1,100); c.position.z=3;
s.add(new THREE.Mesh(new THREE.BoxGeometry(1,1,1), new THREE.MeshNormalMaterial()));
r.render(s,c);
} catch(e) { window.__info = 'ERR ' + e.message; }
</script></body></html>"""

with sync_playwright() as p:
    b = p.chromium.launch(args=['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist', '--enable-webgl'])
    pg = b.new_page(viewport={'width': 800, 'height': 600})
    pg.route('**/three.min.js', lambda route: route.fulfill(body=three, content_type='application/javascript'))
    msgs = []
    pg.on('console', lambda m: msgs.append(m.text))
    pg.on('pageerror', lambda e: msgs.append('PAGEERR ' + str(e)))
    pg.set_content(html)
    pg.wait_for_timeout(500)
    print(pg.evaluate('window.__info'))
    print(msgs)
    pg.screenshot(path=os.path.join(dev, 'smoke.png'))
    b.close()

