load('gen.js');
// usage: jsc evalg.js -- genomeFile seedStart n [diag]
var G = JSON.parse(read(arguments[0])), s0 = +arguments[1], n = +arguments[2], diag = arguments[3];
var f = makeFactory(G), sc = [], leakT = [0, 0, 0, 0, 0, 0, 0], leakAir = 0, leakGround = 0;
var T = ['grunt', 'runner', 'wisp', 'brute', 'splitter', 'mender', 'splitling'];
for (var sd = s0; sd < s0 + n; sd++) {
  var rec = { tick: function (tick, en, tu, hp, gold, wave, ev) { for (var i = 0; i < ev.length; i++) if (ev[i][0] === 'L') leakT[ev[i][2]]++; } };
  var r = rampartSimulate(f, sd, 12020, diag ? rec : undefined);
  sc.push(r.score);
}
var mean = sc.reduce(function (a, b) { return a + b; }, 0) / n;
var sd2 = Math.sqrt(sc.reduce(function (a, b) { return a + (b - mean) * (b - mean); }, 0) / n);
sc.sort(function (a, b) { return a - b; });
print('mean', mean.toFixed(3), 'std', sd2.toFixed(2), 'min', sc[0], 'p10', sc[Math.floor(n * 0.1)], 'median', sc[n >> 1], 'max', sc[n - 1]);
if (diag) print('leaks by type', T.map(function (t, i) { return t + ':' + leakT[i]; }).join(' '));

