var cur = {}, line = [];
var TN2 = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
r.log.forEach(function (e) {
  if (e[1] === 'B') line.push('w' + (Math.floor((e[0] - 20) / 40) + 1) + ' B' + e[2] + ':' + TN2[e[3]]);
