var fin = {};
r.log.forEach(function (e) { if (e[1] === 'B') fin[e[2]] = [TN2[e[3]], 1]; else if (e[1] === 'U') fin[e[2]][1] = e[3]; else if (e[1] === 'S') delete fin[e[2]]; });
var out = []; for (var s = 0; s < 16; s++) out.push(s + ':' + (fin[s] ? fin[s][0] + fin[s][1] : '-'));
print('final', out.join(' '));
var counts = {}; for (s in fin) counts[fin[s][0]] = (counts[fin[s][0]] || 0) + 1; print(JSON.stringify(counts));

