function createStrategy() {
  // Last Rampart strategy.
  //  plan():   an evolved build/upgrade/sell script ("ops") executed in order as gold allows.
  //  target(): per-turret-type target choice. Splash turrets pick the target that maximises the total useful
  //            damage dealt inside the splash zone (enemies about to die waste less), weighted toward enemies
  //            that are close to leaking, and anything within an "urgent" distance of the base goes first.
  // Self-contained: no globals, no randomness, no shared state.
  var G = /*__GENOME__*/;
  var TN = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
  var TIDX = { bolt: 0, cannon: 1, frost: 2, lance: 3, flak: 4 };
  var COST = [50, 90, 70, 120, 80];
  var BASE = [26, 60, 10, 180, 40];
  var SPL = [0, 90, 0, 0, 70];
  var PIERCE = [0, 0, 0, 1, 0];
  var ops = G.ops, tm = G.tm, pm = G.pm, tp = G.tp || {}, idx = 0;
  var WR = tp.wr || [0, 0, 0, 0, 0], URG = tp.urg || [0, 0, 0, 0, 0], KB = tp.kb || [0, 0, 0, 0, 0];
  var dmgTab = [];
  for (var ty = 0; ty < 5; ty++) {
    var d = BASE[ty], row = [d];
    d = Math.floor(d * 16 / 10); row.push(d);
    d = Math.floor(d * 16 / 10); row.push(d);
    dmgTab.push(row);
  }
  return {
    plan: function (s) {
      var acts = [], g = s.gold, cur = [], i;
      for (i = 0; i < 16; i++) {
        var t = s.slots[i].turret;
        cur.push(t ? { ty: TIDX[t.type], tier: t.tier, spent: t.spent } : null);
      }
      while (idx < ops.length && acts.length < 32) {
        var o = ops[idx], sl = o[1], c = cur[sl];
        if (o[0] === 0) {
          if (c) { idx++; continue; }
          var cost = COST[o[2]];
          if (g < cost) break;
          g -= cost; cur[sl] = { ty: o[2], tier: 1, spent: cost };
          acts.push({ op: 'build', slot: sl, type: TN[o[2]] });
        } else if (o[0] === 1) {
          if (!c || c.tier >= 3) { idx++; continue; }
          var uc = COST[c.ty] * c.tier;
          if (g < uc) break;
          g -= uc; c.spent += uc; c.tier++;
          acts.push({ op: 'upgrade', slot: sl });
        } else {
          if (!c) { idx++; continue; }
          g += Math.floor(c.spent * 70 / 100); cur[sl] = null;
          acts.push({ op: 'sell', slot: sl });
        }
        idx++;
      }
      return acts;
    },
    target: function (t, cs) {
      var ty = TIDX[t.type], mode = tm[ty], pri = pm[ty];
      if (mode === 0 && !pri) return -1;
      var best = -1, bs = -1e18, i, j, c, sc, dm = dmgTab[ty][t.tier - 1], R2 = SPL[ty] * SPL[ty];
      var vals = null;
      if (mode === 7) {
        vals = [];
        for (i = 0; i < cs.length; i++) {
          c = cs[i];
          var eff = PIERCE[ty] ? dm : Math.max(1, dm - c.armor);
          var prog = 1 - c.remaining / (c.air ? 2800 : 4600);
          vals.push(Math.min(c.hp, eff) * (1 + WR[ty] * prog) + (c.hp <= eff ? KB[ty] : 0));
        }
      }
      for (i = 0; i < cs.length; i++) {
        c = cs[i];
        if (mode === 0) sc = -c.remaining;
        else if (mode === 1) sc = c.hp;
        else if (mode === 2) sc = c.armor * 100000 - c.remaining;
        else if (mode === 3) {
          var n = 0;
          for (j = 0; j < cs.length; j++) { var dx = cs[j].x - c.x, dy = cs[j].y - c.y; if (dx * dx + dy * dy <= R2) n++; }
          sc = n * 100000 - c.remaining;
        } else if (mode === 4) sc = (c.slowed ? 0 : 100000) - c.remaining;
        else if (mode === 5) sc = -c.hp * 10000 - c.remaining;
        else if (mode === 7) {
          var tot = vals[i];
          if (R2 > 0) {
            tot = 0;
            for (j = 0; j < cs.length; j++) { var ex = cs[j].x - c.x, ey = cs[j].y - c.y; if (ex * ex + ey * ey <= R2) tot += vals[j]; }
          }
          sc = tot * 100 - c.remaining * 0.001;
          if (c.remaining <= URG[ty]) sc += 1e12 - c.remaining;
        } else { var e2 = PIERCE[ty] ? dm : Math.max(1, dm - c.armor); sc = Math.min(c.hp, e2) * 100000 - c.remaining; }
        if (pri && c.type === 'mender') sc += 1e15;
        if (sc > bs) { bs = sc; best = c.id; }
      }
      return best;
    }
  };
}

