var SS = +arguments[0], ITERS = +arguments[1], TS = +arguments[2], TN_ = +arguments[3], startFile = arguments[4];
var rnd = mkrng(SS * 7919 + 13);
function ri(n) { return Math.floor(rnd() * n); }
var seeds = seedRange(TS, TN_);
function clone(G) { return JSON.parse(JSON.stringify(G)); }

function mutate(G) {
  var H = clone(G), k = 1 + (rnd() < 0.3 ? 1 : 0) + (rnd() < 0.1 ? 1 : 0);
  if (!H.tp) H.tp = { wr: [0, 0, 0, 0, 0], urg: [0, 0, 0, 0, 0], kb: [0, 0, 0, 0, 0] };
  for (var m = 0; m < k; m++) {
    var r = rnd(), ops = H.ops, n = ops.length, i, j, o;
    if (r < 0.14) {
      var bs = []; for (i = 0; i < n; i++) if (ops[i][0] === 0) bs.push(i);
      if (bs.length) ops[bs[ri(bs.length)]][2] = ri(5);
    } else if (r < 0.30) { i = ri(n); j = Math.max(0, Math.min(n - 1, i + (ri(9) - 4))); o = ops[i]; ops[i] = ops[j]; ops[j] = o; }
    else if (r < 0.42) { i = ri(n); o = ops.splice(i, 1)[0]; j = Math.max(0, Math.min(ops.length, i + (ri(21) - 10))); ops.splice(j, 0, o); }
    else if (r < 0.50) { var kind = rnd(), s = ri(16); o = kind < 0.35 ? [0, s, ri(5)] : kind < 0.85 ? [1, s] : [2, s]; ops.splice(ri(n + 1), 0, o); }
    else if (r < 0.56) { if (n > 10) ops.splice(ri(n), 1); }
    else if (r < 0.64) { var a = ri(16), b = ri(16); for (i = 0; i < n; i++) { if (ops[i][1] === a) ops[i][1] = b; else if (ops[i][1] === b) ops[i][1] = a; } }
    else if (r < 0.70) { var sl = ri(16), t = ri(5); for (i = 0; i < n; i++) if (ops[i][0] === 0 && ops[i][1] === sl) ops[i][2] = t; }
    else if (r < 0.78) { H.tm[ri(5)] = [0, 3, 7, 7, 7, 1, 6][ri(7)]; }
    else if (r < 0.82) { var q = ri(5); H.pm[q] = 1 - H.pm[q]; }
    else if (r < 0.90) { var q2 = ri(5); H.tp.wr[q2] = Math.max(0, Math.min(6, H.tp.wr[q2] + (ri(2) ? 0.25 : -0.25) * (1 + ri(4)))); }
    else if (r < 0.96) { var q3 = ri(5); H.tp.urg[q3] = Math.max(0, Math.min(2200, H.tp.urg[q3] + (ri(2) ? 100 : -100) * (1 + ri(4)))); }
    else { var q4 = ri(5); H.tp.kb[q4] = Math.max(0, Math.min(400, H.tp.kb[q4] + (ri(2) ? 10 : -10) * (1 + ri(5)))); }
  }
  return H;
}

var cur = JSON.parse(read(startFile));
if (!cur.tp) cur.tp = { wr: [0, 0, 0, 0, 0], urg: [0, 0, 0, 0, 0], kb: [0, 0, 0, 0, 0] };
var curS = evalGenome(cur, seeds), best = cur, bestS = curS;
