for (var it = 0; it < ITERS; it++) {
  var c = mutate(cur), s = evalGenome(c, seeds);
  if (s >= curS) { cur = c; curS = s; if (s > bestS) { best = c; bestS = s; print('IMPROVE it=' + it + ' ' + s.toFixed(3)); } }
}
print('FINAL ' + bestS.toFixed(3));
print('GENOME ' + JSON.stringify(best));

