import os, sys, json
dev = os.path.dirname(os.path.abspath(__file__))
def rd(n): return open(os.path.join(dev, n), encoding='utf-8').read()

strategy = rd('strategy.js').strip('\n')
sim = rd('sim.js').strip('\n')
main = "(function () {\n'use strict';\n" + '\n'.join(rd(n).strip('\n') for n in ['m1_core.js', 'm2_world.js', 'm3_dynamic.js', 'm4_hud_audio_ui.js']) + '\n})();'
shell = rd('shell.html')

DBG_HOOK = ('window.__dbg = {get hudN(){return hudN;}, hudGeo: hudGeo, hudMat: hudMat, renderer: renderer, hudCam: hudCam, drawHud: drawHud, '
            'hudPos: hudPos, hudCol: hudCol, hudUv: hudUv, R: R, scene: scene, camera: camera, updateScene: updateScene, renderAt: renderAt, '
            'pools: {spr: sprPool, ring: ringPool, beam: beamPool, deb: debrisPool}, get AC(){return AC;}, get master(){return master;}, '
            'get voices(){return voices.length;}, get state(){return state;}, get simTime(){return simTime;}};')
main = main.replace('/*__DBG__*/', DBG_HOOK if os.environ.get('DBG') else '')

rep = {}
rp = os.path.join(dev, 'report.json')
if os.path.exists(rp): rep = json.load(open(rp))
main = main.replace("'/*__STRAT_SUMMARY__*/'", json.dumps(rep.get('summary', '')))
main = main.replace('/*__STRAT_SEEDS__*/0', str(rep.get('seedsTested', 0)))
main = main.replace('/*__STRAT_MEAN__*/null', json.dumps(rep['meanScore']) if rep.get('meanScore') is not None else 'null')
main = main.replace('/*__TESTED__*/false', 'true' if rep.get('testedInBrowser') else 'false')
default_systems = "/*__SYSTEMS__*/{ board: 'full', enemiesAndTurrets: 'full', combatVisuals: 'full', fall: 'full', hud: 'full', audio: 'full' }"
if 'systems' in rep: main = main.replace(default_systems, json.dumps(rep['systems']))
else: main = main.replace('/*__SYSTEMS__*/', '')
if 'simplifications' in rep: main = main.replace('/*__SIMPL__*/[]', json.dumps(rep['simplifications']))
else: main = main.replace('/*__SIMPL__*/', '')

for tag in ('</script', '<!--'):
    for name, src in (('strategy', strategy), ('sim', sim), ('main', main)):
        if tag in src:
            print('ERROR: %s contains %s' % (name, tag)); sys.exit(1)

out = shell.replace('/*__STRATEGY__*/', strategy).replace('/*__SIM__*/', sim).replace('/*__MAIN__*/', main)
for marker in ('/*__',):
    if marker in out:
        print('WARNING: unreplaced marker present');
target = sys.argv[1] if len(sys.argv) > 1 else os.path.join(dev, 'index.html')
open(target, 'w', encoding='utf-8').write(out)
print('wrote', target, len(out), 'bytes')

