import sys, os, json, time
from playwright.sync_api import sync_playwright
dev = os.path.dirname(os.path.abspath(__file__))
three = open(os.path.join(dev, 'three.min.js'), 'rb').read()
step = float(sys.argv[2]) if len(sys.argv) > 2 else 0.23
JS = """(step) => {
  const d = window.__dbg; const out = { frames: 0, errors: [], maxEnemies: 0, nan: 0, poolMax: {spr: 0, ring: 0, beam: 0, deb: 0} };
  for (let t = 0; t <= 100.0001; t += step) {
    try {
      d.renderAt(Math.min(100, t)); out.frames++;
      for (const k of ['spr','ring','beam','deb']) out.poolMax[k] = Math.max(out.poolMax[k], d.pools[k].n);
      const p = d.camera.position; if (!isFinite(p.x) || !isFinite(p.y) || !isFinite(p.z)) out.nan++;
      for (const arr of [d.pools.spr.mesh.instanceMatrix.array]) { for (let i = 0; i < d.pools.spr.n * 16; i += 16) { if (!isFinite(arr[i]) || !isFinite(arr[i + 13])) { out.nan++; break; } } }
    } catch (e) { out.errors.push(t.toFixed(2) + ': ' + e.message); if (out.errors.length > 5) break; }
  }
  out.last = d.R.last; out.fall = d.R.fallTick; out.score = d.R.result.score;
  let mx = 0; for (let k = 0; k <= d.R.last; k++) mx = Math.max(mx, d.R.snaps[k].length / 7); out.maxEnemies = mx;
  out.caps = { spr: d.pools.spr.cap, deb: d.pools.deb.cap };
  return out; }"""
with sync_playwright() as p:
    b = p.chromium.launch(args=['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist', '--enable-webgl'])
    pg = b.new_page(viewport={'width': 320, 'height': 180})
    pg.route('**/three.min.js', lambda route: route.fulfill(body=three, content_type='application/javascript'))
    errs = []
    pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.goto('file://' + sys.argv[1]); pg.wait_for_timeout(500)
    pg.click('#btn-toggle')                       # leave the countdown so the page loop is idle (PAUSED)
    t0 = time.time()
    res = pg.evaluate(JS, step)
    print(json.dumps(res)); print('elapsed %.1fs' % (time.time() - t0), 'page errors:', errs[:3])
    b.close()

