import sys, os, re, json
from playwright.sync_api import sync_playwright
html = open(sys.argv[1], encoding='utf-8').read()
def script(i):
    m = re.search(r'<script id="%s">(.*?)</script>' % i, html, re.S)
    return m.group(1)
strategy, sim = script('rampart-strategy'), script('rampart-sim')
page_html = '<!doctype html><html><body><script>%s</script><script>%s</script></body></html>' % (strategy, sim)
seeds = [int(s) for s in (sys.argv[2] if len(sys.argv) > 2 else '1,2,3,4,5').split(',')]
JS = """(seeds) => {
  const out = {};
  const csA = () => ({ plan(s) { const a = []; let g = s.gold; for (const sl of s.slots) if (!sl.turret && g >= 50) { a.push({ op: 'build', slot: sl.slot, type: 'bolt' }); g -= 50; } return a; } });
  const rA = rampartSimulate(csA, 42, 12020); out.A = [rA.score, rA.fallTick, rA.log.length, rA.hash];
  const csB = () => ({ plan(s) { if (s.wave === 1) return [{op:'build',slot:3,type:'cannon'},{op:'build',slot:6,type:'frost'}];
    if (s.wave === 3) return [{op:'upgrade',slot:3},{op:'build',slot:12,type:'flak'}]; if (s.wave === 6) return [{op:'build',slot:8,type:'lance'},{op:'sell',slot:6}]; return []; } });
  const rB = rampartSimulate(csB, 7, 12020); out.B = [rB.score, rB.fallTick, rB.log.length, rB.hash];
  const r42 = rampartSimulate(createStrategy, 42, 2020); out.s42 = [r42.score, r42.fallTick, r42.log.length, r42.hash];
  out.globals = Object.keys(window).filter(k => ['createStrategy', 'rampartSimulate'].includes(k));
  out.games = []; let tot = 0;
  for (const s of seeds) { const t0 = performance.now(); const r = rampartSimulate(createStrategy, s, 12020); const ms = performance.now() - t0; out.games.push([s, r.score, Math.round(ms)]); tot += r.score; }
  out.mean = tot / seeds.length;
  // determinism: same seed twice -> same hash
  out.det = rampartSimulate(createStrategy, 9, 12020).hash === rampartSimulate(createStrategy, 9, 12020).hash;
  // two strategies share no state
  const s1 = createStrategy(), s2 = createStrategy(); out.indep = s1 !== s2 && s1.plan !== s2.plan;
  return out; }"""
with sync_playwright() as p:
    b = p.chromium.launch()
    pg = b.new_page()
    errs = []
    pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.set_content(page_html)
    print(json.dumps(pg.evaluate(JS, seeds)))
    print('errors:', errs)
    b.close()

